response:
```jsx
function Counter() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setCount(c => c + 1), 1000);
    return () => clearInterval(id);
  }, []);
  return <h1>{count}</h1>;
}
```

**Why:** The effect runs only once (empty dependency array), so the interval callback closes over the initial `count` of 0 and calls `setCount(0 + 1)` every second, leaving it stuck at 1. Using the functional updater `c => c + 1` makes React supply the latest state each tick, so the effect doesn't need to depend on `count`.

# Paystack Payment Endpoints for Express.js

This delivers two endpoints:

- **`POST /payments/initialize`** creates a pending order and returns a Paystack checkout URL.
- **`POST /webhooks/paystack`** verifies the webhook signature and marks the order paid. If the same webhook arrives twice, the order is still marked paid only once.

It uses PostgreSQL and Node 18+, which provides built-in `fetch`.

## `schema.sql`

```sql
CREATE TABLE orders (
  id                       BIGSERIAL PRIMARY KEY,
  reference                TEXT        NOT NULL UNIQUE,
  email                    TEXT        NOT NULL,
  amount_kobo              BIGINT      NOT NULL CHECK (amount_kobo > 0),
  currency                 TEXT        NOT NULL DEFAULT 'NGN',
  status                   TEXT        NOT NULL DEFAULT 'pending'
                           CHECK (status IN ('pending', 'paid', 'failed', 'needs_review')),
  paystack_transaction_id  BIGINT      UNIQUE,
  paid_at                  TIMESTAMPTZ,
  created_at               TIMESTAMPTZ NOT NULL DEFAULT now()
);
```

## `server.js`

```js
'use strict';

const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');

const PAYSTACK_SECRET_KEY = process.env.PAYSTACK_SECRET_KEY;
const PAYSTACK_CALLBACK_URL = process.env.PAYSTACK_CALLBACK_URL; // optional
const PAYSTACK_BASE = 'https://api.paystack.co';

if (!PAYSTACK_SECRET_KEY) {
  throw new Error('PAYSTACK_SECRET_KEY is not set');
}

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const app = express();

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Convert a naira amount ("2500", "2500.5", 2500.75) to integer kobo
 * without floating-point error. Returns null if invalid.
 */
function nairaToKobo(input) {
  const str = typeof input === 'number' ? input.toString() : String(input ?? '').trim();
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(str);
  if (!match) return null;
  const kobo = BigInt(match[1]) * 100n + BigInt((match[2] || '').padEnd(2, '0') || '0');
  if (kobo <= 0n || kobo > BigInt(Number.MAX_SAFE_INTEGER)) return null;
  return Number(kobo);
}

function generateReference() {
  return `ord_${Date.now()}_${crypto.randomBytes(8).toString('hex')}`;
}

function isValidPaystackSignature(rawBody, signatureHeader) {
  if (!signatureHeader || typeof signatureHeader !== 'string') return false;
  const expected = crypto
    .createHmac('sha512', PAYSTACK_SECRET_KEY)
    .update(rawBody)
    .digest('hex');

  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(signatureHeader, 'utf8');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

async function paystackRequest(path, { method = 'GET', body } = {}) {
  const res = await fetch(`${PAYSTACK_BASE}${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${PAYSTACK_SECRET_KEY}`,
      'Content-Type': 'application/json',
    },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(15000),
  });
  const json = await res.json().catch(() => null);
  if (!res.ok || !json || json.status !== true) {
    const msg = json?.message || `HTTP ${res.status}`;
    throw new Error(`Paystack ${method} ${path} failed: ${msg}`);
  }
  return json.data;
}

/* ------------------------------------------------------------------ */
/* Webhook: registered BEFORE express.json() so we get the raw body.  */
/* The HMAC must be computed over the exact bytes Paystack sent.       */
/* ------------------------------------------------------------------ */

app.post(
  '/webhooks/paystack',
  express.raw({ type: 'application/json', limit: '1mb' }),
  async (req, res) => {
    // 1. Verify that the request is from Paystack.
    if (!Buffer.isBuffer(req.body) ||
        !isValidPaystackSignature(req.body, req.get('x-paystack-signature'))) {
      return res.sendStatus(401);
    }

    let event;
    try {
      event = JSON.parse(req.body.toString('utf8'));
    } catch {
      return res.sendStatus(400);
    }

    // Acknowledge events we don't handle so Paystack stops retrying them.
    if (event?.event !== 'charge.success') {
      return res.sendStatus(200);
    }

    const reference = event.data?.reference;
    if (!reference) return res.sendStatus(200);

    try {
      // 2. Re-confirm with Paystack's API (defence in depth). Trust the
      //    verified transaction, not just the webhook payload.
      const tx = await paystackRequest(
        `/transaction/verify/${encodeURIComponent(reference)}`
      );

      if (tx.status !== 'success') {
        return res.sendStatus(200);
      }

      // 3. Idempotent, atomic transition: only a 'pending' order whose
      //    amount and currency match can become 'paid'. A duplicate webhook
      //    finds the order already 'paid', updates 0 rows, and does nothing.
      const update = await pool.query(
        `UPDATE orders
            SET status = 'paid',
                paid_at = now(),
                paystack_transaction_id = $2
          WHERE reference = $1
            AND status = 'pending'
            AND amount_kobo = $3
            AND currency = $4
        RETURNING id, email, amount_kobo`,
        [reference, tx.id, tx.amount, tx.currency]
      );

      if (update.rowCount === 1) {
        const order = update.rows[0];
        console.info(`Order ${order.id} marked paid (ref ${reference})`);
        // Run one-time side effects here (fulfilment, receipt email, etc.).
        // They run only on this branch, so a duplicate webhook cannot trigger them again.
        return res.sendStatus(200);
      }

      // Zero rows updated: find out why.
      const { rows } = await pool.query(
        'SELECT id, status, amount_kobo, currency FROM orders WHERE reference = $1',
        [reference]
      );
      const order = rows[0];

      if (!order) {
        console.warn(`Webhook for unknown reference ${reference}`);
      } else if (order.status === 'paid') {
        console.info(`Duplicate webhook ignored for order ${order.id} (ref ${reference})`);
      } else if (order.amount_kobo !== Number(tx.amount) || order.currency !== tx.currency) {
        // Paid amount doesn't match: never auto-fulfil. Flag it for a person to review.
        await pool.query(
          `UPDATE orders SET status = 'needs_review'
            WHERE id = $1 AND status = 'pending'`,
          [order.id]
        );
        console.error(
          `Amount/currency mismatch on order ${order.id}: expected ` +
          `${order.amount_kobo} ${order.currency}, got ${tx.amount} ${tx.currency}`
        );
      }

      // Return 200 so Paystack doesn't retry a request we've intentionally handled.
      return res.sendStatus(200);
    } catch (err) {
      // Transient failure (DB down, Paystack verify failed): return 5xx so
      // Paystack retries later. The idempotent UPDATE makes retries safe.
      console.error('Paystack webhook processing failed:', err);
      return res.sendStatus(500);
    }
  }
);

/* ------------------------------------------------------------------ */
/* JSON body parsing for all other routes                              */
/* ------------------------------------------------------------------ */

app.use(express.json({ limit: '10kb' }));

/* ------------------------------------------------------------------ */
/* Start a payment                                                     */
/* ------------------------------------------------------------------ */

app.post('/payments/initialize', async (req, res) => {
  const email = typeof req.body?.email === 'string' ? req.body.email.trim() : '';
  const amountKobo = nairaToKobo(req.body?.amount);

  if (!EMAIL_RE.test(email)) {
    return res.status(400).json({ error: 'A valid email is required.' });
  }
  if (amountKobo === null) {
    return res.status(400).json({
      error: 'amount must be a positive naira value with at most 2 decimal places.',
    });
  }

  const reference = generateReference();

  // Record the order first so the webhook always has something to match.
  await pool.query(
    `INSERT INTO orders (reference, email, amount_kobo, currency, status)
     VALUES ($1, $2, $3, 'NGN', 'pending')`,
    [reference, email, amountKobo]
  );

  try {
    const data = await paystackRequest('/transaction/initialize', {
      method: 'POST',
      body: {
        email,
        amount: amountKobo,          // Paystack expects the smallest unit (kobo)
        currency: 'NGN',
        reference,
        ...(PAYSTACK_CALLBACK_URL && { callback_url: PAYSTACK_CALLBACK_URL }),
      },
    });

    return res.status(201).json({
      reference,
      authorizationUrl: data.authorization_url,
      accessCode: data.access_code,
    });
  } catch (err) {
    console.error('Paystack initialize failed:', err);
    await pool.query(
      `UPDATE orders SET status = 'failed' WHERE reference = $1 AND status = 'pending'`,
      [reference]
    ).catch(() => {});
    return res.status(502).json({ error: 'Could not start payment. Please try again.' });
  }
});

/* ------------------------------------------------------------------ */

app.use((err, req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

const port = Number(process.env.PORT) || 3000;
app.listen(port, () => console.log(`Listening on :${port}`));
```

## Setup

```bash
npm install express pg
export PAYSTACK_SECRET_KEY=sk_test_xxx
export DATABASE_URL=postgres://user:pass@localhost:5432/shop
export PAYSTACK_CALLBACK_URL=https://yourapp.com/payment/complete   # optional
psql "$DATABASE_URL" -f schema.sql
node server.js
```

In the Paystack Dashboard, go to Settings → API Keys & Webhooks and set the webhook URL to `https://yourapp.com/webhooks/paystack`.

**Example request:**

```bash
curl -X POST http://localhost:3000/payments/initialize \
  -H 'Content-Type: application/json' \
  -d '{"email":"customer@example.com","amount":"2500.50"}'
```

Redirect the customer to the returned `authorizationUrl`.

## How the requirements are handled

**Naira to kobo**
- Paystack expects amounts in kobo.
- The conversion parses the value as a string instead of multiplying floats, so `"19.99"` becomes exactly `1999` with no rounding error.

**Checking the webhook is genuine**
- Paystack signs each webhook body with HMAC-SHA512, using your secret key, and sends the result in the `x-paystack-signature` header.
- The webhook route uses `express.raw()` and is registered before `express.json()`. This matters because the signature only matches the exact raw bytes Paystack sent.
- The signatures are compared with `crypto.timingSafeEqual`.
- The handler then calls `GET /transaction/verify/:reference` and acts on Paystack's answer rather than trusting the webhook payload alone.

**Duplicate webhooks**
- Paystack retries webhooks and can send the same one more than once.
- The order is marked paid with a single conditional update: `UPDATE ... WHERE reference = $1 AND status = 'pending'`.
- The database runs this atomically. Even if two copies arrive at the same moment, only one can change the order from `pending` to `paid`. The other updates 0 rows, is logged as a duplicate, and gets a `200` response.
- One-time side effects (fulfilment, receipts) belong only in the `rowCount === 1` branch, so they run exactly once.
- The `UNIQUE` constraint on `paystack_transaction_id` adds a second guard.

**Wrong amount or currency**
- The order is only marked paid if the amount and currency Paystack confirms match what was stored for that order.
- If they don't match, the order is set to `needs_review` instead of being fulfilled.

**Retry behaviour**
- Temporary errors (database or network failures) return `500`, so Paystack will retry later.
- Requests the handler has deliberately processed or ignored return `200`, so Paystack stops resending them.
- Because marking the order paid is idempotent, retries are always safe.

**Optional hardening**
- You can also restrict the webhook route to Paystack's published webhook IP addresses (currently `52.31.139.75`, `52.49.173.169` and `52.214.14.220`). If you do, check the list in Paystack's docs, and configure `app.set('trust proxy', ...)` correctly if you run behind a proxy.

## Setup

```bash
npm init -y
npm i express better-sqlite3
```

Requires Node 18+ (for built-in `fetch`). Set `PAYSTACK_SECRET_KEY` in your environment.

## `server.js`

```js
const crypto = require("crypto");
const express = require("express");
const Database = require("better-sqlite3");

const PAYSTACK_SECRET_KEY = process.env.PAYSTACK_SECRET_KEY;
if (!PAYSTACK_SECRET_KEY) throw new Error("PAYSTACK_SECRET_KEY is not set");

const app = express();
const db = new Database("orders.db");

db.exec(`
  CREATE TABLE IF NOT EXISTS orders (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    reference    TEXT NOT NULL UNIQUE,
    email        TEXT NOT NULL,
    amount_kobo  INTEGER NOT NULL,
    status       TEXT NOT NULL DEFAULT 'pending',   -- pending | paid
    paid_at      TEXT,
    created_at   TEXT NOT NULL DEFAULT (datetime('now'))
  );
  -- One row per processed webhook event. The PRIMARY KEY is what makes
  -- duplicate deliveries safe.
  CREATE TABLE IF NOT EXISTS webhook_events (
    event_key    TEXT PRIMARY KEY,
    received_at  TEXT NOT NULL DEFAULT (datetime('now'))
  );
`);

/* ------------------------------------------------------------------ */
/* 1. Webhook — registered BEFORE express.json() because signature     */
/*    verification needs the exact raw bytes Paystack sent.            */
/* ------------------------------------------------------------------ */

const markPaid = db.transaction((eventKey, reference, paidAmountKobo, currency) => {
  // Idempotency gate: if this event was already processed, insert is a no-op.
  const inserted = db
    .prepare("INSERT OR IGNORE INTO webhook_events (event_key) VALUES (?)")
    .run(eventKey);
  if (inserted.changes === 0) return "duplicate";

  const order = db.prepare("SELECT * FROM orders WHERE reference = ?").get(reference);
  if (!order) return "unknown_order";

  if (currency !== "NGN" || paidAmountKobo !== order.amount_kobo) {
    console.error("Amount/currency mismatch", { reference, paidAmountKobo, currency, expected: order.amount_kobo });
    return "amount_mismatch";
  }

  // Conditional update: only transitions pending -> paid, so even without the
  // gate above, a replay cannot re-apply the change.
  const res = db
    .prepare(
      "UPDATE orders SET status = 'paid', paid_at = datetime('now') WHERE reference = ? AND status = 'pending'"
    )
    .run(reference);
  return res.changes === 1 ? "paid" : "already_paid";
});

app.post(
  "/webhooks/paystack",
  express.raw({ type: "application/json", limit: "1mb" }),
  (req, res) => {
    const signature = req.get("x-paystack-signature");
    if (!signature || !Buffer.isBuffer(req.body)) return res.sendStatus(401);

    const expected = crypto
      .createHmac("sha512", PAYSTACK_SECRET_KEY)
      .update(req.body)
      .digest("hex");

    const a = Buffer.from(expected, "utf8");
    const b = Buffer.from(signature, "utf8");
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.sendStatus(401);
    }

    let event;
    try {
      event = JSON.parse(req.body.toString("utf8"));
    } catch {
      return res.sendStatus(400);
    }

    // Only act on successful charges; acknowledge everything else.
    if (event.event !== "charge.success" || event.data?.status !== "success") {
      return res.sendStatus(200);
    }

    const { reference, amount, currency, id } = event.data;
    const eventKey = `charge.success:${id ?? reference}`;

    try {
      const result = markPaid(eventKey, reference, amount, currency);
      console.log(`Webhook ${eventKey} -> ${result}`);
      // Always 200 for duplicates so Paystack stops retrying.
      return res.sendStatus(200);
    } catch (err) {
      // Transaction rolled back, so the event isn't recorded; Paystack will retry.
      console.error("Webhook processing failed", err);
      return res.sendStatus(500);
    }
  }
);

/* ------------------------------------------------------------------ */
/* 2. Initialize payment                                               */
/* ------------------------------------------------------------------ */

app.use(express.json());

app.post("/payments/initialize", async (req, res) => {
  const { email, amount } = req.body ?? {};

  if (typeof email !== "string" || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return res.status(400).json({ error: "A valid email is required" });
  }
  if (typeof amount !== "number" || !Number.isFinite(amount) || amount <= 0) {
    return res.status(400).json({ error: "amount must be a positive number (naira)" });
  }
  const amountKobo = Math.round(amount * 100);
  if (Math.abs(amountKobo - amount * 100) > 1e-6) {
    return res.status(400).json({ error: "amount cannot have more than 2 decimal places" });
  }

  const reference = `ord_${crypto.randomUUID()}`;

  try {
    db.prepare("INSERT INTO orders (reference, email, amount_kobo) VALUES (?, ?, ?)")
      .run(reference, email, amountKobo);

    const psRes = await fetch("https://api.paystack.co/transaction/initialize", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${PAYSTACK_SECRET_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        email,
        amount: amountKobo, // Paystack expects kobo
        currency: "NGN",
        reference,
        // callback_url: "https://yourapp.com/payment/complete",
      }),
    });

    const body = await psRes.json();
    if (!psRes.ok || !body.status) {
      console.error("Paystack initialize failed", body);
      return res.status(502).json({ error: "Could not start payment" });
    }

    return res.status(201).json({
      reference,
      authorization_url: body.data.authorization_url,
      access_code: body.data.access_code,
    });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: "Internal error" });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Listening on ${PORT}`));
```

## Usage

```bash
PAYSTACK_SECRET_KEY=sk_test_xxx node server.js

curl -X POST localhost:3000/payments/initialize \
  -H 'Content-Type: application/json' \
  -d '{"email":"customer@example.com","amount":2500.50}'
```

Redirect the customer to the returned `authorization_url`. In the Paystack dashboard (Settings → API Keys & Webhooks), set the webhook URL to `https://your-domain/webhooks/paystack`.

## How it works

- **Amount handling:** naira is converted to kobo (`×100`) and rounded. Values with more than 2 decimals are rejected.
- **Authenticity:** the webhook computes an HMAC-SHA512 of the raw request body with your secret key and compares it to `x-paystack-signature` using a timing-safe comparison. The route uses `express.raw`, because parsing the JSON first would change the bytes and break the signature.
- **Duplicates:** two layers protect against a repeated webhook.
  1. `webhook_events.event_key` is a primary key, so a repeated event's insert is ignored and the handler returns 200 without doing anything.
  2. The order update is `... WHERE status = 'pending'`, so it can only move to `paid` once.

  Both steps run in one SQLite transaction. If anything fails, the event isn't recorded and a 500 makes Paystack retry.
- **Tamper check:** the order is marked paid only if the webhook's amount and currency match what was stored when the payment started.

## Production notes

- With Postgres or MySQL, keep the same pattern: a unique constraint on the event key and a conditional `UPDATE ... WHERE status = 'pending'`, both in one transaction.
- Do fulfilment (emails, shipping) after the order moves to `paid`, ideally via a queue, so webhook responses stay fast.
- Optionally restrict the webhook route to Paystack's published IPs as an extra layer. The signature check remains the primary defence.

input:
This React component should show a counter that goes up by 1 every second, but it stays stuck at 1. Fix it and explain why in two sentences.

```jsx
function Counter() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setCount(count + 1), 1000);
    return () => clearInterval(id);
  }, []);
  return <h1>{count}</h1>;
}
```

response:
```jsx
function Counter() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setCount(c => c + 1), 1000);
    return () => clearInterval(id);
  }, []);
  return <h1>{count}</h1>;
}
```

The effect runs only once because of the empty dependency array, so the interval callback keeps the `count` from the first render (`0`) and calls `setCount(0 + 1)` every second. The functional updater `setCount(c => c + 1)` always gets the latest state from React, so the counter goes up correctly without re-creating the interval.

```js
// app.js
// Requires Node 18+ (global fetch), and these packages: npm i express pg
//
// Schema:
//   CREATE TABLE orders (
//     id           BIGSERIAL PRIMARY KEY,
//     reference    TEXT UNIQUE NOT NULL,
//     email        TEXT NOT NULL,
//     amount_kobo  BIGINT NOT NULL,
//     currency     TEXT NOT NULL DEFAULT 'NGN',
//     status       TEXT NOT NULL DEFAULT 'pending',
//     paystack_transaction_id BIGINT,
//     paid_at      TIMESTAMPTZ
//   );
//   CREATE TABLE webhook_events (
//     event_key    TEXT PRIMARY KEY,
//     event_type   TEXT NOT NULL,
//     received_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
//     payload      JSONB NOT NULL
//   );
//
// Env: PAYSTACK_SECRET_KEY, DATABASE_URL, APP_BASE_URL, PORT (optional)

import express from 'express';
import crypto from 'node:crypto';
import pg from 'pg';

const PAYSTACK_SECRET = process.env.PAYSTACK_SECRET_KEY;
const APP_BASE_URL = process.env.APP_BASE_URL;
const PAYSTACK_API = 'https://api.paystack.co';

if (!PAYSTACK_SECRET || !process.env.DATABASE_URL || !APP_BASE_URL) {
  throw new Error('Missing PAYSTACK_SECRET_KEY, DATABASE_URL, or APP_BASE_URL');
}

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
const app = express();

// ---------------------------------------------------------------------------
// 1. Start a payment
//    POST /payments/initialize  { "email": "...", "amountNaira": 2500.50 }
// ---------------------------------------------------------------------------
app.post('/payments/initialize', express.json(), async (req, res) => {
  const { email, amountNaira } = req.body ?? {};

  if (typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return res.status(400).json({ error: 'A valid email is required' });
  }

  // Naira -> kobo (Paystack amounts are integers in the smallest unit)
  const amountKobo = Math.round(Number(amountNaira) * 100);
  if (!Number.isSafeInteger(amountKobo) || amountKobo <= 0) {
    return res.status(400).json({ error: 'amountNaira must be a positive number' });
  }

  const reference = `ord_${crypto.randomUUID()}`;

  // Create the order first so the webhook always has something to match.
  const { rows } = await pool.query(
    `INSERT INTO orders (reference, email, amount_kobo, currency, status)
     VALUES ($1, $2, $3, 'NGN', 'pending')
     RETURNING id`,
    [reference, email, amountKobo]
  );

  let psRes;
  try {
    psRes = await fetch(`${PAYSTACK_API}/transaction/initialize`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${PAYSTACK_SECRET}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email,
        amount: amountKobo,
        currency: 'NGN',
        reference,
        callback_url: `${APP_BASE_URL}/payments/callback`,
        metadata: { order_id: rows[0].id },
      }),
    });
  } catch (err) {
    console.error('Paystack initialize network error', err);
    return res.status(502).json({ error: 'Payment provider unreachable' });
  }

  const body = await psRes.json().catch(() => ({}));
  if (!psRes.ok || !body.status) {
    console.error('Paystack initialize failed', psRes.status, body);
    await pool.query(`UPDATE orders SET status = 'failed' WHERE reference = $1`, [reference]);
    return res.status(502).json({ error: 'Could not start payment' });
  }

  return res.status(201).json({
    orderId: rows[0].id,
    reference,
    authorizationUrl: body.data.authorization_url,
  });
});

// ---------------------------------------------------------------------------
// 2. Paystack webhook
//    POST /webhooks/paystack
//    Must use the RAW body for signature verification, so this route is
//    registered before any global express.json() and uses express.raw().
// ---------------------------------------------------------------------------
app.post(
  '/webhooks/paystack',
  express.raw({ type: 'application/json' }),
  async (req, res) => {
    // --- 2a. Verify the signature -----------------------------------------
    const signature = req.get('x-paystack-signature');
    if (!signature) return res.sendStatus(401);

    const expected = crypto
      .createHmac('sha512', PAYSTACK_SECRET)
      .update(req.body)
      .digest();

    const received = Buffer.from(signature, 'hex');
    if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
      return res.sendStatus(401);
    }

    // --- 2b. Parse the event ----------------------------------------------
    let event;
    try {
      event = JSON.parse(req.body.toString('utf8'));
    } catch {
      return res.sendStatus(400);
    }

    // Acknowledge events we don't care about so Paystack stops retrying them.
    if (event.event !== 'charge.success') {
      return res.sendStatus(200);
    }

    const data = event.data ?? {};
    // Paystack transaction IDs are unique per transaction, so this key
    // identifies the event even if the same webhook is delivered twice.
    const eventKey = `${event.event}:${data.id}`;

    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      // --- 2c. Idempotency: claim this event. Duplicates insert nothing. --
      const claimed = await client.query(
        `INSERT INTO webhook_events (event_key, event_type, payload)
         VALUES ($1, $2, $3)
         ON CONFLICT (event_key) DO NOTHING
         RETURNING event_key`,
        [eventKey, event.event, event]
      );

      if (claimed.rowCount === 0) {
        await client.query('ROLLBACK');
        return res.status(200).json({ status: 'duplicate, already processed' });
      }

      // --- 2d. Look up the order and lock it -------------------------------
      const { rows } = await client.query(
        `SELECT id, status, amount_kobo, currency
           FROM orders
          WHERE reference = $1
          FOR UPDATE`,
        [data.reference]
      );
      const order = rows[0];

      if (!order) {
        console.error('Webhook for unknown reference', data.reference);
        await client.query('COMMIT');
        return res.sendStatus(200);
      }

      // --- 2e. Check the payment actually matches the order ----------------
      const amountOk = Number(order.amount_kobo) === Number(data.amount);
      const currencyOk = data.currency === order.currency;
      const statusOk = data.status === 'success';

      if (!amountOk || !currencyOk || !statusOk) {
        console.error('Webhook mismatch', {
          reference: data.reference,
          expectedKobo: order.amount_kobo,
          gotKobo: data.amount,
          currency: data.currency,
          status: data.status,
        });
        // Keep the event record so it isn't reprocessed; do not mark paid.
        await client.query('COMMIT');
        return res.sendStatus(200);
      }

      // --- 2f. Mark paid (no-op if already paid) ---------------------------
      if (order.status !== 'paid') {
        await client.query(
          `UPDATE orders
              SET status = 'paid',
                  paid_at = now(),
                  paystack_transaction_id = $2
            WHERE id = $1`,
          [order.id, data.id]
        );
      }

      await client.query('COMMIT');
      return res.sendStatus(200);
    } catch (err) {
      await client.query('ROLLBACK');
      console.error('Webhook processing failed', err);
      // 500 makes Paystack retry the delivery later.
      return res.sendStatus(500);
    } finally {
      client.release();
    }
  }
);

// Everything after the webhook can use JSON parsing normally.
app.get('/payments/callback', (req, res) => {
  // Paystack redirects the customer here. Do not mark orders paid from this
  // redirect; rely on the webhook. You may poll order status for the UI.
  res.send('Payment received. We are confirming it now.');
});

const port = process.env.PORT ?? 3000;
app.listen(port, () => console.log(`Listening on :${port}`));
```

**Notes**

- **Authenticity:** Paystack signs each webhook body with HMAC-SHA512 using your secret key and sends it in `x-paystack-signature`. The handler checks this over the raw bytes with a constant-time comparison. Unsigned or altered requests get a 401.
- **Duplicates:** The event key `charge.success:<transaction id>` is inserted into `webhook_events` with a primary key constraint. A repeat delivery hits the conflict, inserts nothing, and returns 200 without touching the order. Because the claim and the order update share one transaction, a crash mid-processing rolls both back, so Paystack's retry can still succeed.
- **Correctness checks:** Before marking an order paid, the handler confirms the amount in kobo, the currency, and the status against the stored order. A mismatch is logged and the order is left unpaid.
- **Retries:** Unknown references return 200 so Paystack stops retrying. Server errors return 500 so Paystack retries.
- **Optional hardening:** You can also restrict the webhook route to Paystack's published IP addresses, and call `GET /transaction/verify/:reference` before marking an order paid.
